import React, { useEffect, useState } from "react";
import Menu from "./Menu";

const TopBar = () => {
  const [nifty, setNifty] = useState(null);
  const [sensex, setSensex] = useState(null);

  const getMarketData = async () => {
    try {
      const res = await fetch(
        "https://query1.finance.yahoo.com/v7/finance/quote?symbols=%5ENSEI,%5EBSESN"
      );
      const data = await res.json();

      const niftyData = data.quoteResponse.result[0];
      const sensexData = data.quoteResponse.result[1];

      setNifty(niftyData);
      setSensex(sensexData);
    } catch (error) {
      console.log("Error fetching market data:", error);
    }
  };

  useEffect(() => {
    getMarketData();
    const interval = setInterval(getMarketData, 3000); // 3 sec refresh

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="topbar-container">
      <div className="indices-container">

        <div className="nifty">
          <p className="index">NIFTY 50</p>
          <p className="index-points">
            {nifty ? nifty.regularMarketPrice : "Loading..."}
          </p>
          <p
            className="percent"
            style={{
              color:
                nifty?.regularMarketChangePercent > 0 ? "green" : "red",
            }}
          >
            {nifty
              ? nifty.regularMarketChangePercent.toFixed(2) + "%"
              : ""}
          </p>
        </div>

        <div className="sensex">
          <p className="index">SENSEX</p>
          <p className="index-points">
            {sensex ? sensex.regularMarketPrice : "Loading..."}
          </p>
          <p
            className="percent"
            style={{
              color:
                sensex?.regularMarketChangePercent > 0 ? "green" : "red",
            }}
          >
            {sensex
              ? sensex.regularMarketChangePercent.toFixed(2) + "%"
              : ""}
          </p>
        </div>

      </div>

      <Menu />
    </div>
  );
};

export default TopBar;
